import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CWgsre3x.js";const m=JSON.parse('{"title":"Installation & Deployment","description":"","frontmatter":{},"headers":[],"relativePath":"installation/index.md","filePath":"installation/index.md"}'),r={name:"installation/index.md"};function o(s,e,d,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="installation-deployment" tabindex="-1">Installation &amp; Deployment <a class="header-anchor" href="#installation-deployment" aria-label="Permalink to &quot;Installation &amp; Deployment&quot;">​</a></h1><p>This guide explains how to prepare an authorized TransferBook+ environment, onboard a transportation business and manage releases safely. It complements <a href="/system-requirements/">System Requirements</a>.</p><div class="warning custom-block"><p class="custom-block-title">Availability and responsibility</p><p>This is a deployment-readiness guide, not a downloadable installer, a promise of self-hosting availability or a service-level agreement. Obtain the approved release, deployment instructions, access arrangements and support terms from the provider before activation. Features are subject to release acceptance, company permissions and integration readiness.</p></div><h2 id="choose-the-deployment-arrangement" tabindex="-1">Choose the deployment arrangement <a class="header-anchor" href="#choose-the-deployment-arrangement" aria-label="Permalink to &quot;Choose the deployment arrangement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arrangement</th><th>Customer responsibilities</th><th>Hosting responsibilities</th></tr></thead><tbody><tr><td>Managed hosting, where offered</td><td>Provide business configuration, authorized users and acceptance feedback</td><td>Provision and maintain the agreed environment, backups, monitoring and release process</td></tr><tr><td>Dedicated hosting, subject to approval</td><td>Agree capacity, access, security responsibilities and support scope</td><td>Validate the release-specific infrastructure and operational procedures</td></tr><tr><td>Self-managed deployment, if explicitly supported</td><td>Assign qualified technical staff and accept agreed maintenance responsibilities</td><td>Supply only the approved release package and documented support scope</td></tr></tbody></table><p>Browser users do not install a local application runtime or database. Do not attempt to install a demonstration build or an arbitrary source snapshot as a production system.</p><h2 id="managed-onboarding" tabindex="-1">Managed onboarding <a class="header-anchor" href="#managed-onboarding" aria-label="Permalink to &quot;Managed onboarding&quot;">​</a></h2><ol><li>Confirm the company, approved environment, installed release, authorized administrator and support contact.</li><li>Configure operating markets, time zones, languages, pickup and drop-off locations, fleet and driver records.</li><li>Review vehicle classes, rates, taxes, currency, tariffs, booking modes and operational policies with the company.</li><li>Assign individual accounts and least-privilege roles; review which staff can see or modify reservations, dispatch and financial information.</li><li>Enable only the approved booking channels and integrations. Keep unapproved providers disabled.</li><li>Validate representative reservations, quotations, assignments and payment review using synthetic data in an approved test environment.</li><li>Obtain operational sign-off before accepting real bookings. Agree support, maintenance and incident reporting arrangements.</li></ol><p>See <a href="/plus/markets-and-locations.html">markets and locations</a>, <a href="/plus/company-and-language-settings.html">company settings</a>, <a href="/plus/fleet-management.html">fleet management</a>, <a href="/plus/pricing.html">pricing</a> and <a href="/developers/permissions.html">roles and permissions</a>.</p><h2 id="dedicated-hosting-readiness" tabindex="-1">Dedicated hosting readiness <a class="header-anchor" href="#dedicated-hosting-readiness" aria-label="Permalink to &quot;Dedicated hosting readiness&quot;">​</a></h2><p>For authorized infrastructure teams only:</p><ul><li>Confirm the supported runtime and database versions, capacity plan, release artifacts and integrity verification procedure.</li><li>Prepare separate service and database identities with minimum privileges; store secrets outside publicly served files and source control.</li><li>Configure approved DNS, HTTPS, reverse proxy, supervised services, restricted database access and monitoring.</li><li>Isolate production, staging and demonstration data and credentials. Never treat a demonstration endpoint as an authorized deployment target.</li><li>Review the release-specific database migration plan and confirm backups and recovery compatibility before changing schemas.</li><li>Document the maintenance window, affected users, support owner, rollback conditions and acceptance procedure.</li></ul><p>The <a href="/system-requirements/#server-and-hosting-requirements">hosting requirements</a> are planning baselines, not guaranteed capacity limits. Internal hostnames, paths, credentials and live deployment commands are intentionally excluded from public documentation.</p><h2 id="release-and-update-lifecycle" tabindex="-1">Release and update lifecycle <a class="header-anchor" href="#release-and-update-lifecycle" aria-label="Permalink to &quot;Release and update lifecycle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Required evidence</th></tr></thead><tbody><tr><td>Prepare</td><td>Approved version and source revision, integrity checks, release notes and change scope</td></tr><tr><td>Validate</td><td>Build and tests pass; staging acceptance uses synthetic records</td></tr><tr><td>Protect</td><td>Verified backup, recovery plan, maintenance arrangements and migration review</td></tr><tr><td>Activate</td><td>Authorized release procedure for the intended environment</td></tr><tr><td>Accept</td><td>Health, access, reservation, dispatch and integration checks pass</td></tr><tr><td>Close</td><td>Record the deployed version, acceptance results, outstanding limitations and recovery reference</td></tr></tbody></table><p>Use the <a href="/release-notes/">Release Notes</a> to review documented changes. The release-specific procedure takes precedence over this overview. Do not assume that every update is reversible: a schema or data change may require a separate restoration or forward-recovery procedure.</p><h2 id="backup-and-disaster-recovery" tabindex="-1">Backup and disaster recovery <a class="header-anchor" href="#backup-and-disaster-recovery" aria-label="Permalink to &quot;Backup and disaster recovery&quot;">​</a></h2><p>Agree backup frequency, retention, encryption, off-system storage, restore access and recovery objectives before launch. Actual recovery point and recovery time objectives must be established by the service agreement and tested; no numerical guarantees are implied here.</p><p>A recovery plan should cover the database, required configuration, release artifacts and user-managed content. Keep protected secrets in a separately controlled recovery process. Test restoration into an isolated environment, verify tenant boundaries and record the result. Retain the last known-good compatible release and define who can authorize rollback.</p><p>If an incident interrupts a reservation or payment, verify its authoritative status before resubmitting. Avoid duplicate bookings or charges. Follow <a href="/developers/idempotency.html">retry-safe reservation creation</a> and <a href="/tutorials/payment-review.html">payment review</a>.</p><h2 id="go-live-acceptance-checklist" tabindex="-1">Go-live acceptance checklist <a class="header-anchor" href="#go-live-acceptance-checklist" aria-label="Permalink to &quot;Go-live acceptance checklist&quot;">​</a></h2><ul><li>Confirm the intended environment and approved application release.</li><li>Verify HTTPS, login, logout, session expiry and role boundaries.</li><li>Verify booking and quotation flows, including a quick booking without passenger email.</li><li>Check pricing, operating locations, vehicle classes, driver and vehicle assignment, and dispatch scheduling.</li><li>Test approved notifications, payment providers, external dispatch and public channels only where enabled.</li><li>Confirm monitoring, backup restoration evidence, support ownership and operational fallback arrangements.</li><li>Document unresolved defects and hold activation of any workflow that has not passed its acceptance criteria.</li></ul><p>For training, see <a href="/tutorials/">Tutorials</a>. For operational problems, see <a href="/help/">Help Centre</a> and <a href="/integrations/activation-and-channels.html">Integration readiness and channels</a>.</p><p><a href="/el/installation/">Ελληνικά</a></p><p>Before go-live, review <a href="/security-privacy/">Security, Privacy &amp; GDPR</a>.</p>',25)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
